import{_ as a,o as r,c as e,ae as l}from"./chunks/framework.CkRokae0.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"sessions/04-adr/what-is-adr.md","filePath":"sessions/04-adr/what-is-adr.md"}'),i={name:"sessions/04-adr/what-is-adr.md"};function o(s,t,n,d,h,u){return r(),e("div",null,[...t[0]||(t[0]=[l('<h2 id="要約" tabindex="-1">要約 <a class="header-anchor" href="#要約" aria-label="Permalink to &quot;要約&quot;">​</a></h2><p>ADR（Architecture Decision Record）は「その判断をなぜしたか」を短く記録するドキュメント手法です。ソフトウェア開発における<strong>重要な判断の意図</strong>を残し、将来的に同じ判断の検証や変更判断を速くします。</p><h2 id="本質-判断プロセスを記録する理由" tabindex="-1">本質：判断プロセスを記録する理由 <a class="header-anchor" href="#本質-判断プロセスを記録する理由" aria-label="Permalink to &quot;本質：判断プロセスを記録する理由&quot;">​</a></h2><p>通常、重要な判断は以下のような背景で行われます：</p><ul><li>複数の選択肢がある（DB は PostgreSQL か MongoDB か、など）</li><li>トレードオフがある（スピード vs 耐障害性、など）</li><li>当時の前提や制約がある（チームのスキル、プロジェクト規模、など）</li></ul><p>しかし、その判断が記録されなければ：</p><ul><li>数ヶ月後に「なぜこうしているんだ」と思う</li><li>新しいメンバーが同じ議論を繰り返す</li><li>前提が変わったことに気づかず不適切な判断のまま続く</li></ul><p><strong>ADR はこのギャップを埋めます</strong>。判断した時点での背景・代替案・トレードオフを短く残すことで、将来の読者が判断の根拠を理解でき、検証や変更判断が迅速になります。</p><h2 id="adr-の標準構成-三要素" tabindex="-1">ADR の標準構成（三要素） <a class="header-anchor" href="#adr-の標準構成-三要素" aria-label="Permalink to &quot;ADR の標準構成（三要素）&quot;">​</a></h2><ul><li><strong>Context（背景・前提）</strong>: なぜこの判断が必要だったか、どんな制約や要件があったか</li><li><strong>Decision（決定）</strong>: 最終的に選んだ案と、簡潔な理由</li><li><strong>Consequences（帰結）</strong>: その判断で起こること、注意点、リスク、実装のポイント</li></ul><h2 id="他ドキュメントとの違い" tabindex="-1">他ドキュメントとの違い <a class="header-anchor" href="#他ドキュメントとの違い" aria-label="Permalink to &quot;他ドキュメントとの違い&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ドキュメント</th><th>目的</th><th>対象</th><th>更新頻度</th></tr></thead><tbody><tr><td><strong>設計書</strong></td><td>システム構成・仕様を説明</td><td>現在の状態</td><td>設計変更時</td></tr><tr><td><strong>議事録</strong></td><td>議論や会議の内容を記録</td><td>議論プロセス</td><td>その場限り</td></tr><tr><td><strong>ADR</strong></td><td>判断の根拠を記録</td><td>決定の意図</td><td>ほぼ不変（検証時のみ）</td></tr></tbody></table><p>設計書は「現在どうなっているか」を説明し、議事録は「誰が何を言ったか」を残し、ADR は「なぜそうしたか」を残す点が特徴です。</p><h2 id="adr-が向いている判断の種類" tabindex="-1">ADR が向いている判断の種類 <a class="header-anchor" href="#adr-が向いている判断の種類" aria-label="Permalink to &quot;ADR が向いている判断の種類&quot;">​</a></h2><h3 id="技術・アーキテクチャ選定" tabindex="-1">技術・アーキテクチャ選定 <a class="header-anchor" href="#技術・アーキテクチャ選定" aria-label="Permalink to &quot;技術・アーキテクチャ選定&quot;">​</a></h3><ul><li>DB（PostgreSQL vs MongoDB vs Redis など）</li><li>言語やフレームワーク（React vs Vue、Django vs FastAPI など）</li><li>キャッシュ戦略（メモリキャッシュ vs Redis、TTL 設定 など）</li></ul><h3 id="設計方針" tabindex="-1">設計方針 <a class="header-anchor" href="#設計方針" aria-label="Permalink to &quot;設計方針&quot;">​</a></h3><ul><li>API バージョニング戦略（URL パス vs ヘッダー vs 共存 など）</li><li>認証・認可の仕組み（JWT vs セッション、RBAC vs ABAC など）</li><li>エラーハンドリング（例外vs戻り値、エラーコード体系 など）</li></ul><h3 id="運用・プロセス" tabindex="-1">運用・プロセス <a class="header-anchor" href="#運用・プロセス" aria-label="Permalink to &quot;運用・プロセス&quot;">​</a></h3><ul><li>リリース戦略（カナリアデプロイ、ブルーグリーンデプロイ など）</li><li>バックアップ・復旧戦略（バージョニング、RPO/RTO など）</li><li>監視・アラート設定（メトリクス選定、閾値 など）</li></ul><p><strong>共通点</strong>：決定が<strong>長期に影響</strong>し、<strong>後で質問されそう</strong>な、<strong>重要度が高い</strong>判断。</p><h2 id="adr-が向かない判断" tabindex="-1">ADR が向かない判断 <a class="header-anchor" href="#adr-が向かない判断" aria-label="Permalink to &quot;ADR が向かない判断&quot;">​</a></h2><ul><li><strong>細かい実装</strong>（変数名、関数分割方法、フォーマット）</li><li><strong>毎日のように変わる設定</strong>（一時的なパフォーマンス調整値）</li><li><strong>自明な判断</strong>（仕様から自動的に決まる）</li><li><strong>可逆的な決定</strong>（簡単に戻せて、影響がない）</li></ul><p>理由：過剰ドキュメント化によってメンテナンス負荷が増し、実務的でなくなります。</p><hr><h2 id="ナビゲーション" tabindex="-1">ナビゲーション <a class="header-anchor" href="#ナビゲーション" aria-label="Permalink to &quot;ナビゲーション&quot;">​</a></h2><p><a href="./why-adr.html">次へ: なぜ使うか →</a> · <a href="./">ADRトップへ</a></p>',27)])])}const p=a(i,[["render",o]]);export{g as __pageData,p as default};
